"""Persistent shared JSON cache for public demonstration profiles."""
import json
import os
import tempfile
import time
from contextlib import contextmanager

try:
    import fcntl
except ImportError:
    fcntl = None

from app.config import CACHE_PATH, CACHE_TTL

LOCK_PATH = CACHE_PATH + '.lock'


def get_or_load(key, loader, now=None):
    """Return the cached value for `key`, refreshing it once it is older than CACHE_TTL."""
    stamp = time.time() if now is None else float(now)
    entry = _read_entries().get(key)
    if _is_fresh(entry, stamp):
        return entry['value']
    value = loader()
    _store(key, value, stamp)
    return value


def _is_fresh(entry, now):
    if not isinstance(entry, dict) or 'value' not in entry:
        return False
    stored_at = entry.get('stored_at')
    if isinstance(stored_at, bool) or not isinstance(stored_at, (int, float)):
        return False
    return (now - stored_at) < CACHE_TTL


def _read_entries():
    try:
        with open(CACHE_PATH, encoding='utf-8') as handle:
            entries = json.load(handle)
    except (OSError, ValueError):
        return {}
    return entries if isinstance(entries, dict) else {}


def _store(key, value, stamp):
    try:
        json.dumps(value)
    except (TypeError, ValueError):
        return
    with _exclusive_lock():
        entries = {k: v for k, v in _read_entries().items() if _is_fresh(v, stamp)}
        entries[key] = {'stored_at': stamp, 'value': value}
        _write_entries(entries)


def _write_entries(entries):
    directory = os.path.dirname(CACHE_PATH) or '.'
    temporary = None
    try:
        os.makedirs(directory, exist_ok=True)
        descriptor, temporary = tempfile.mkstemp(dir=directory, prefix='.profiles-', suffix='.tmp')
        with os.fdopen(descriptor, 'w', encoding='utf-8') as handle:
            json.dump(entries, handle, ensure_ascii=False)
        os.replace(temporary, CACHE_PATH)
    except (OSError, ValueError):
        if temporary is not None:
            try:
                os.unlink(temporary)
            except OSError:
                pass


@contextmanager
def _exclusive_lock():
    handle = None
    if fcntl is not None:
        try:
            os.makedirs(os.path.dirname(LOCK_PATH) or '.', exist_ok=True)
            handle = open(LOCK_PATH, 'a+')
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
        except OSError:
            if handle is not None:
                handle.close()
            handle = None
    try:
        yield
    finally:
        if handle is not None:
            try:
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
            except OSError:
                pass
            handle.close()
