"""Shared cache headers for public synthetic profiles."""
from flask import has_request_context, request

from app.config import CACHE_TTL

PROFILE_PATH_PREFIX = '/api/accounts/'
PROFILE_PATH_SUFFIX = '/profile'
CACHEABLE_METHODS = ('GET', 'HEAD')


def apply_response_policy(response):
    """Mark successful public profile responses as shareable for CACHE_TTL seconds."""
    if _is_cacheable_profile(response):
        response.headers['Cache-Control'] = 'public, max-age=%d' % CACHE_TTL
    return response


def _is_cacheable_profile(response):
    if not 200 <= response.status_code < 300:
        return False
    if not has_request_context() or request.method not in CACHEABLE_METHODS:
        return False
    path = request.path
    return path.startswith(PROFILE_PATH_PREFIX) and path.endswith(PROFILE_PATH_SUFFIX)
