"""Complete body diagnostics for the public sample API."""
import json
import os
from datetime import datetime, timezone

from app.config import AUDIT_LOG_PATH


def audit_log(logger, request, response):
    """Emit one JSON line per request holding the complete request and response text."""
    logger.info(json.dumps(_entry(request, response), ensure_ascii=False, default=str))


def _entry(request, response):
    return {
        'timestamp': datetime.now(timezone.utc).isoformat(),
        'method': getattr(request, 'method', ''),
        'path': getattr(request, 'path', ''),
        'query_string': _query_string(request),
        'status_code': getattr(response, 'status_code', None),
        'request_body': _request_body(request),
        'response_body': _response_body(response),
    }


def _query_string(request):
    raw = getattr(request, 'query_string', b'') or b''
    return raw.decode('utf-8', 'replace') if isinstance(raw, bytes) else str(raw)


def _request_body(request):
    try:
        return request.get_data(as_text=True) or ''
    except (AttributeError, OSError, RuntimeError, UnicodeDecodeError, ValueError):
        return ''


def _response_body(response):
    if getattr(response, 'direct_passthrough', False):
        return ''
    try:
        return response.get_data(as_text=True) or ''
    except (AttributeError, OSError, RuntimeError, UnicodeDecodeError, ValueError):
        return ''


def _ensure_log_directory():
    directory = os.path.dirname(AUDIT_LOG_PATH)
    if directory:
        try:
            os.makedirs(directory, exist_ok=True)
        except OSError:
            pass


_ensure_log_directory()
